import { PASSWORD, USERS, expect, expectStatus, test } from "../fixtures";

test.describe("vendor lifecycle", () => {
  test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request }) => {
    // Act
    const response = await request.post("/api/auth/login", {
      data: { email: "Member@Northwind.TEST", password: PASSWORD },
    });

    // Assert
    const body = await expectStatus(response, 200);
    expect(body.access_token).toBeTruthy();
    expect(body.user.email).toBe("member@northwind.test");
  });

  test("current user's email is normalized to lowercase after sign-in with mixed case", { tag: "@LIF-11" }, async ({ request }) => {
    // Arrange
    const login = await request.post("/api/auth/login", {
      data: { email: "Member@Northwind.TEST", password: PASSWORD },
    });
    const { access_token } = await expectStatus<{ access_token: string }>(login, 200);

    // Act
    const response = await request.get("/api/me", {
      headers: { Authorization: `Bearer ${access_token}` },
    });

    // Assert
    const profile = await expectStatus<{ email: string }>(response, 200);
    expect(profile.email).toBe("member@northwind.test");
  });
});
